Path resolveSymlinkChain(Path p) throws IOException {
    Path current = p;
    java.util.Set<Path> visited = new java.util.HashSet<>();
    while (Files.isSymbolicLink(current)) {
        if (!visited.add(current.toAbsolutePath().normalize())) {
            break;
        }
        Path target = Files.readSymbolicLink(current);
        if (!target.isAbsolute()) {
            Path parent = current.getParent();
