void deleteFileAndSymlinkTarget(Path path) throws IOException {
    if (Files.isSymbolicLink(path)) {
        List<Path> chain = new ArrayList<>();
        Path current = path;
        Set<Path> visited = new HashSet<>();
        while (Files.isSymbolicLink(current) && visited.add(current.toAbsolutePath().normalize())) {
            chain.add(current);
            Path symTarget = Files.readSymbolicLink(current);
            if (!symTarget.isAbsolute()) {
                Path parent = current.getParent();
                symTarget = parent != null ? parent.resolve(symTarget).normalize() : symTarget;
            }
            current = symTarget;
        }
        if (Files.exists(current)) {
            Files.delete(current);
        }
        for (int i = chain.size() - 1; i >= 0; i--) {
            Path symlink = chain.get(i);
            Files.deleteIfExists(symlink);
        }
    } else {
        Files.delete(path);
    }
}

